const updateCustomerPrimaryAction = () => {
    const button = el('confirmCustomerDataBtn');
    const stateBadge = el('customerActionState');
    const hint = el('customerActionHint');
    if (!button || !stateBadge || !hint) return;
    if (!state.selectedChat) {
        button.textContent = 'Salvar dados';
        button.disabled = true;
        stateBadge.textContent = 'selecione';
        stateBadge.className = 'badge orange';
        hint.textContent = 'Selecione um cliente para ver a proxima acao.';
        return;
    }
    const brazilTestOnly = isBrazilBlockedRecord(state.selectedChat);
    const draft = customerDraftFromForm();
    const missing = missingCustomerFields(draft);
    const qualityBlocked = state.customerDataResolution?.version === 28 && state.customerDataResolution.orderDataReady !== true;
    const status = normalizePanelStatus(draft.status || state.selectedChat.orderStatus || '');
    if (brazilTestOnly) {
        button.textContent = 'BR teste bloqueado';
        button.disabled = true;
        stateBadge.textContent = 'bloqueado';
        stateBadge.className = 'badge red';
        hint.textContent = 'Numero interno/teste nao confirma cliente real.';
        return;
    }
    if (status === 'comprar_depois') {
        button.textContent = 'Salvar dados';
        button.disabled = customerFormSaveBusy();
        stateBadge.textContent = completeBuyLaterDateV217() ? 'agendar' : 'aguarda data';
        stateBadge.className = 'badge orange';
        hint.textContent = 'Preencha dia e mês; o ano já está preenchido. Clique em Salvar dados para confirmar Comprar depois.';
        return;
    }
    if (['confirmado', 'pedido_enviado', 'entregue', 'recompra'].includes(status)) {
        button.textContent = 'Salvar dados';
        button.disabled = customerFormSaveBusy();
        stateBadge.textContent = status === 'confirmado' && (missing.length || qualityBlocked) ? 'dados bloqueados' : status === 'confirmado' ? 'confirmar pedido' : status.replace(/_/g, ' ');
        stateBadge.className = `badge ${status === 'confirmado' && (missing.length || qualityBlocked) ? 'red' : 'green'}`;
        hint.textContent = status === 'confirmado' && (missing.length || qualityBlocked)
            ? `Nao confirma enquanto faltar: ${missing.map((item) => item.label).join(', ') || 'validacao de qualidade'}.`
            : status === 'confirmado'
            ? 'Ao salvar, este cliente entra automaticamente em Pedidos confirmados.'
            : 'Pedido ja esta em fluxo. Use Salvar dados apenas para corrigir a ficha.';
        return;
    }
    button.disabled = customerFormSaveBusy();
    if (missing.length) {
        button.textContent = 'Salvar dados';
        stateBadge.textContent = `${missing.length} faltando`;
        stateBadge.className = 'badge orange';
        hint.textContent = `Pode salvar parcial. Falta para confirmar pedido: ${missing.map((item) => item.label).join(', ')}.`;
    } else {
        button.textContent = 'Salvar dados';
        stateBadge.textContent = 'pronto';
        stateBadge.className = 'badge green';
        hint.textContent = 'Dados completos. Para confirmar pedido, escolha Confirmar pedido no Status.';
    }
};

